Object.assign(I18N.content, {"letters":{"ا":["Alif","Lleva la vocal; suena como a"],"ب":["Bā","Sonido b"],"ت":["Tā","Sonido t"],"ث":["Thā","Como la z de «zapato» (España)"],"ج":["Yīm","Como «y» fuerte, «dy»"],"ح":["Ḥā","h aspirada desde el centro de la garganta"],"خ":["Jā","Como la j española"],"د":["Dāl","Sonido d"],"ذ":["Dhāl","Como la d suave de «nada»"],"ر":["Rā","r vibrante"],"ز":["Zāy","z sonora, como en inglés «zoo»"],"س":["Sīn","Sonido s"],"ش":["Shīn","sh, como en inglés «show»"],"ص":["Ṣād","s enfática y grave"],"ض":["Ḍād","d enfática y grave"],"ط":["Ṭā","t enfática y grave"],"ظ":["Ẓā","d suave enfática"],"ع":["ʿAyn","Sonido sonoro del centro de la garganta"],"غ":["Ghayn","Como una gárgara, r francesa"],"ف":["Fā","Sonido f"],"ق":["Qāf","k profunda, desde el fondo de la lengua"],"ك":["Kāf","Sonido k"],"ل":["Lām","Sonido l"],"م":["Mīm","Sonido m"],"ن":["Nūn","Sonido n"],"و":["Wāw","Sonido w; como vocal larga ū"],"ه":["Hā","h suave y aspirada"],"ي":["Yā","Sonido y; como vocal larga ī"]},"syl":{"بَ":"ba","تَ":"ta","سَ":"sa","لَ":"la","مَ":"ma","نَ":"na","قَ":"qa","صَ":"ṣa","طَ":"ṭa","بِ":"bi","تِ":"ti","سِ":"si","لِ":"li","مِ":"mi","نِ":"ni","قِ":"qi","صِ":"ṣi","طِ":"ṭi","بُ":"bu","تُ":"tu","سُ":"su","لُ":"lu","مُ":"mu","نُ":"nu","قُ":"qu","صُ":"ṣu","طُ":"ṭu","مِنْ":"min","لَمْ":"lam","قُلْ":"qul","هُمْ":"hum","عَنْ":"ʿan","قَدْ":"qad","بَلْ":"bal","كُنْ":"kun","إِنَّ":"inna","ثُمَّ":"thumma","رَبِّ":"rabbi","كُلُّ":"kullu","عَمَّ":"ʿamma","بً":"ban","بٍ":"bin","بٌ":"bun","تً":"tan","تٍ":"tin","تٌ":"tun","قً":"qan","قٍ":"qin","قٌ":"qun","بَا":"bā","بِي":"bī","بُو":"bū","نَا":"nā","نِي":"nī","نُو":"nū","قَا":"qā","قِي":"qī","قُو":"qū"},"marks":{"بَ":"Una pequeña raya inclinada sobre la letra. Se lee con «a»: بَ → ba.","بِ":"Una pequeña raya inclinada bajo la letra. Se lee con «i»: بِ → bi.","بُ":"Una pequeña wāw sobre la letra. Se lee con «u»: بُ → bu.","مِنْ":"Un pequeño círculo sobre la letra. La letra queda sin vocal y se une a la anterior: مِنْ → min.","إِنَّ":"Una pequeña «w» sobre la letra. La letra se duplica: إِنَّ → in-na.","بً":"Tanwin: se añade una «n» a la vocal. Fathatan → «an».","بٍ":"Tanwin: kasratan → «in».","بٌ":"Tanwin: dammatan → «un».","بَا":"Alargamiento: Alif, Wāw y Yā tras una letra vocalizada alargan el sonido: بَا bā, بِي bī, بُو bū."},"words":{"رَبّ":["rabb","Señor"],"كِتَاب":["kitāb","libro"],"يَوْم":["yaum","día"],"دِين":["dīn","religión"],"نَاس":["nās","gente"],"نُور":["nūr","luz"],"قَلْب":["qalb","corazón"],"عِلْم":["ʿilm","conocimiento"],"مَاء":["māʾ","agua"],"شَمْس":["shams","sol"],"قَمَر":["qamar","luna"],"أَرْض":["arḍ","tierra"],"سَمَاء":["samāʾ","cielo"],"رَحْمَة":["raḥma","misericordia"],"سَلَام":["salām","paz"],"صَلَاة":["ṣalāh","oración"],"حَقّ":["ḥaqq","verdad"],"جَنَّة":["yanna","paraíso, jardín"],"خَيْر":["jair","el bien"],"رَسُول":["rasūl","mensajero"],"إِلَٰه":["ilāh","dios, divinidad"],"أَحَد":["aḥad","uno, único"],"مَلِك":["malik","rey"],"قُلْ":["qul","¡di!"]},"surahs":{"fatiha":{"name":"Al-Fatiha","read":["Bismillāhir-raḥmānir-raḥīm","Al-ḥamdu lillāhi rabbil-ʿālamīn","Ar-raḥmānir-raḥīm","Māliki yawmid-dīn","Iyyāka naʿbudu wa iyyāka nastaʿīn","Ihdinaṣ-ṣirāṭal-mustaqīm","Ṣirāṭal-ladhīna anʿamta ʿalayhim ghayril-maghḍūbi ʿalayhim wa laḍ-ḍāllīn"],"mean":["En el nombre de Dios, el Compasivo con toda la creación, el Misericordioso con los creyentes","Todas las alabanzas son para Dios, Señor de todo cuanto existe","el Compasivo, el Misericordioso","Soberano absoluto del Día del Juicio Final","solo a Ti te adoramos y solo de Ti imploramos ayuda","¡Guíanos por el camino recto","El camino de los que has colmado con Tus favores, no el de los que cayeron en Tu ira, ni el de los que se extraviaron"]},"ihlas":{"name":"Al-Ijlas","read":["Qul huwallāhu aḥad","Allāhuṣ-ṣamad","Lam yalid wa lam yūlad","Wa lam yakul-lahū kufuwan aḥad"],"mean":["Di: \"Él es Al-lah, Uno","Al-lah es el Absoluto","No engendró ni fue engendrado","Y no hay nada ni nadie que sea semejante a Él"]},"kevser":{"name":"Al-Kawthar","read":["Innā aʿṭaynākal-kawthar","Faṣalli li rabbika wanḥar","Inna shāniʾaka huwal-abtar"],"mean":["[¡Oh, Mujámmad!] te he agraciado con la abundancia","Reza a tu Señor y sacrifica [los animales en Su nombre]","Porque a quien te desdeñe y odie le privaré de todo bien"]},"felak":{"name":"Al-Falaq","read":["Qul aʿūdhu bi rabbil-falaq","Min sharri mā khalaq","Wa min sharri ghāsiqin idhā waqab","Wa min sharrin-naffāthāti fil-ʿuqad","Wa min sharri ḥāsidin idhā ḥasad"],"mean":["Di: \"Me refugio en el Señor del amanecer","de todo el mal que existe en lo que Él creó","del mal de la oscuridad de la noche cuando se extiende","del mal de las [hechiceras] sopladoras de nudos","y del mal del envidioso cuando envidia"]},"nas":{"name":"An-Nas","read":["Qul aʿūdhu bi rabbin-nās","Malikin-nās","Ilāhin-nās","Min sharril-waswāsil-khannās","Alladhī yuwaswisu fī ṣudūrin-nās","Minal-jinnati wan-nās"],"mean":["Di: \"Me refugio en el Señor de los seres humanos","en el Rey Soberano de los seres humanos","en el [único] Dios de los seres humanos","de la maldad del [demonio] susurrador que huye [cuando el nombre de Dios es mencionado]","que susurra en los corazones de los seres humanos","y existe entre los yinnes y entre los seres humanos"]}}});
